        "lightRadiusFt": 0,
        "baseDamage": "While mounted on a living beast, you can ride to the local watering hole without needing to make a Check. But during an action scene or when exploring Giant Gopher Hole Flats, your mount might panic, and you might get tossed for 1d6 bludgeoning for every 10ft Move your mount has, plus its size value. Don’t land in a cactus patch! Make an Unopposed Skill Check. On Success, your mount doesn’t stumble, and you stay upright.",
